-- evt:pass
RegisterEvent(19, "Door", function(continueStep)
    if continueStep == 2 then
        evt.SetDoorState(8, DoorAction.Trigger)
        XeenQuests.hook("m17.password")
        return
    end
    if continueStep ~= nil then
        XeenQuests.hook("m17.password_wrong")
        return
    end
    evt.SetMessage("Who do you seek?")
    evt.AskQuestion(19, 1, 0, 2, "Answer?", {"Ellinger"})
end, "Door")

