-- evt:question
RegisterEvent(21, "Door", function(continueStep)
    local eventId = 21
    if not (IsQBitSet(QBit(111340))) then
        if continueStep == 1 or continueStep == 2 then
            XeenQuests.hook("m17.question_right")
            return
        end
        if continueStep == 3 then
            XeenQuests.hook("m17.question_wrong")
            AskChoiceWithAnswerSteps(eventId, 5, "Begone!", {{Answer = "Leave the tower", Step = 5}})
            return
        end
        if continueStep == 5 then
            evt.MoveToMap(2560, 9216, 1152, 0, 0, 0, 0, 0, "xeen_d1.odm", {direct = true})
            return
        end
        if continueStep ~= nil then
            return
        end
        XeenQuests.hook("m17.question")
        AskChoiceWithAnswerSteps(eventId, 4, "Answer the question:", {{Answer = "Let him take up his sword", Step = 1}, {Answer = "Cut him down", Step = 2}, {Answer = "I just don't know", Step = 3}})
        return
    end
    evt.SetDoorState(9, DoorAction.Trigger)
end, "Door")

