-- evt:sorcerer_book
RegisterEvent(27, "Book of Sorcerer's Knowledge", function()
    if IsPlayerBitSet(PlayerBit(11312)) then
        XeenQuests.hook("m17.sorcerer_book_again")
        return
    end
    if IsAtLeast(ActualIntellect, 20) then
        AddValue(BaseIntellect, 2)
        SetPlayerBit(PlayerBit(11312))
        XeenQuests.hook("m17.sorcerer_book")
        return
    end
    local hp = 0
    for v = 10, 5000, 10 do
        if not IsAtLeast(HP, v) then break end
        hp = v
    end
    evt.DamagePlayer(Players.Current, const.Damage.Physical, math.max(5, hp // 10))
    XeenQuests.hook("m17.sorcerer_book_hurt")
end, "Book of Sorcerer's Knowledge")

